// Helper to add chapters
function addChapters(bookId, chs) {
  for (const ch of chs) {
    chapters.push({
      id: nextId++,
      book_id: bookId,
      chapter_index: ch.chapter_index,
      title: ch.title,
      description: ch.description,
      image: ch.image,
      monster_avatar: ch.monster_avatar,
      victory_text: ch.victory_text,
      words: ch.words,
      created_at: "2026-06-04T22:00:00.000Z"
    });
  }
}

